      scheduled_at TEXT,
      published_at TEXT,
      created_by TEXT NOT NULL DEFAULT 'blog-engine',
      generation_version TEXT NOT NULL DEFAULT 'blog-engine-v2.0',
      content_version INTEGER NOT NULL DEFAULT 1,
      retry_count INTEGER NOT NULL DEFAULT 0,
