CREATE TABLE blog_engine_article_metrics (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      article_id TEXT NOT NULL,
      period_start TEXT NOT NULL,
      period_end TEXT NOT NULL,
      page_views INTEGER,
      users INTEGER,
      sessions INTEGER,
      organic_traffic INTEGER,
      social_referral INTEGER,
      search_impressions INTEGER,
      search_clicks INTEGER,
      ctr REAL,
      average_engagement_time INTEGER,
      cta_clicks INTEGER,
      conversion_events INTEGER,
      performance_score REAL,
      score_breakdown_json TEXT NOT NULL DEFAULT '{}',
      data_quality TEXT NOT NULL DEFAULT 'partial',
      sample_size INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE blog_engine_improvement_recommendations (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      article_id TEXT,
      recommendation_type TEXT NOT NULL,
      title TEXT NOT NULL,
      summary TEXT NOT NULL DEFAULT '',
      reason TEXT NOT NULL DEFAULT '',
      evidence_json TEXT NOT NULL DEFAULT '{}',
      expected_effect TEXT NOT NULL DEFAULT '',
      risk_level TEXT NOT NULL DEFAULT 'low',
      rollback_plan TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL DEFAULT 'proposed',
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      applied_at TEXT
    );
CREATE TABLE blog_engine_social_contents (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      source_article_id TEXT NOT NULL,
      platform TEXT NOT NULL,
      format TEXT NOT NULL,
      angle TEXT NOT NULL,
      content TEXT NOT NULL,
