      published_at TEXT,
      status TEXT NOT NULL DEFAULT 'queued',
      generation_version TEXT NOT NULL DEFAULT 'blog-sns-link-v1.0',
      campaign_id TEXT,
      tracking_id TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(tenant_id, tracking_id)
    );
