CREATE TABLE blog_engine_social_metrics (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      social_content_id TEXT NOT NULL,
      source_article_id TEXT NOT NULL,
      platform TEXT NOT NULL,
      impressions INTEGER,
      reach INTEGER,
      views INTEGER,
      likes INTEGER,
      comments INTEGER,
      shares INTEGER,
      saves INTEGER,
      profile_actions INTEGER,
      link_clicks INTEGER,
      ctr REAL,
      referral_sessions INTEGER,
      conversion_events INTEGER,
      attribution_type TEXT NOT NULL DEFAULT 'unknown',
      data_quality TEXT NOT NULL DEFAULT 'partial',
      sample_size INTEGER NOT NULL DEFAULT 0,
      fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE blog_engine_optimization_guard (
      tenant_id TEXT PRIMARY KEY,
      enabled INTEGER NOT NULL DEFAULT 1,
      mode TEXT NOT NULL DEFAULT 'recommend',
      brand_score_threshold INTEGER NOT NULL DEFAULT 80,
      safety_score_threshold INTEGER NOT NULL DEFAULT 90,
      max_posts_per_day INTEGER NOT NULL DEFAULT 1,
      max_posts_per_week INTEGER NOT NULL DEFAULT 3,
      locked_settings_json TEXT NOT NULL DEFAULT '{}',
      paused_reason TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
INSERT INTO "blog_engine_optimization_guard" ("tenant_id","enabled","mode","brand_score_threshold","safety_score_threshold","max_posts_per_day","max_posts_per_week","locked_settings_json","paused_reason","created_at","updated_at") VALUES('luna-starwind',1,'recommend',80,90,1,3,'{"human_approval_required":true,"no_external_auto_publish":true}',NULL,'2026-08-15 19:41:31','2026-08-15 19:41:31');
